BEGIN;
SET LOCAL statement_timeout='15s';
SET LOCAL lock_timeout='5s';
DO $block$
DECLARE payload jsonb := $data$[{"language":"es","slug":"salsa-inglesa","public_path":"/salsa-inglesa","title":"Salsa inglesa casera rápida con tamarindo","excerpt":"Prepara salsa inglesa casera con vinagre, tamarindo, melaza y soja. Una versión rápida sin fermentación para sazonar carnes, verduras y guisos.","summary":"Prepara salsa inglesa casera con vinagre, tamarindo, melaza y soja. Una versión rápida sin fermentación para sazonar carnes, verduras y guisos.","ingredients":[{"amount":"250","unit":"ml","name":"vinagre de manzana al 5 % de acidez"},{"amount":"100","unit":"ml","name":"agua"},{"amount":"50","unit":"ml","name":"salsa de soja"},{"amount":"40","unit":"g","name":"melaza de caña"},{"amount":"20","unit":"g","name":"pasta de tamarindo sin semillas y sin azúcar"},{"amount":"30","unit":"g","name":"cebolla blanca"},{"amount":"5","unit":"g","name":"ajo pelado"},{"amount":"5","unit":"g","name":"jengibre fresco pelado"},{"amount":"0.5","unit":"g","name":"pimienta negra molida"},{"amount":"2","unit":"","name":"clavos de olor enteros"},{"amount":"2","unit":"","name":"pimienta de Jamaica en grano"}],"steps":[{"title":"Mide los ingredientes","content":"Mide las cantidades indicadas. Reserva una botella limpia con tapa y una jarra graduada.","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp","image_alt":"Mide los ingredientes"},{"title":"Pica los aromáticos","content":"Pica finamente la cebolla, el ajo y el jengibre.","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp","image_alt":"Pica los aromáticos"},{"title":"Combina los líquidos","content":"Vierte el vinagre, los 100 ml de agua y la salsa de soja en un cazo de acero inoxidable de 1 litro.","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp","image_alt":"Combina los líquidos"},{"title":"Disuelve la melaza y el tamarindo","content":"Incorpora la melaza y la pasta de tamarindo; remueve hasta dispersarlas.","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp","image_alt":"Disuelve la melaza y el tamarindo"},{"title":"Añade los aromáticos y las especias","content":"Añade la cebolla, el ajo, el jengibre, la pimienta negra, los clavos y la pimienta de Jamaica.","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp","image_alt":"Añade los aromáticos y las especias"},{"title":"Calienta la mezcla","content":"Lleva la mezcla a un hervor suave a fuego medio, unos 5 minutos."},{"title":"Cocina a fuego suave","content":"Baja el fuego y cocina destapado durante 20 minutos, con burbujas pequeñas. Remueve de vez en cuando; debe quedar fluida.","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp","image_alt":"Cocina a fuego suave"},{"title":"Cuela la salsa","content":"Pasa la salsa caliente por un colador fino a una jarra resistente al calor. Desecha los sólidos.","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp","image_alt":"Cuela la salsa"},{"title":"Enfría la salsa","content":"Deja perder el calor intenso unos 30 minutos. No la mantengas fuera de la nevera más de 2 horas."},{"title":"Comprueba el rendimiento","content":"Mide la salsa colada: el rendimiento aproximado es de 300 ml. Si se redujo demasiado, añade un poco de agua recién hervida hasta alcanzar 300 ml."},{"title":"Guarda en nevera","content":"Pasa a la botella limpia, tapa y refrigera. Usa utensilios limpios y agita antes de servir.","image_url":"/recetas/salsa-inglesa-casera/portada.webp","image_alt":"Guarda en nevera"}],"category":"Salsas y aderezos","cuisine":"Inspiración británica","difficulty":"Fácil","course":"Condimento","prep_time_minutes":10,"cook_time_minutes":25,"total_time_minutes":65,"servings":20,"image_url":"/recetas/salsa-inglesa-casera/portada.webp","content_html":"","notes":"<p>Versión casera rápida inspirada en Worcestershire; no reproduce una salsa comercial fermentada. Contiene soja y puede contener trigo: revisa la etiqueta de la soja. No añadas sal sin probar. Empieza con 1 cucharadita por porción de guiso o aderezo y ajusta. Mantén refrigerada a 4 °C o menos y úsala en 4 días; congela porciones si necesitas conservarla más. No es una conserva estable a temperatura ambiente.</p>","keywords":["Salsa inglesa casera rápida con tamarindo"],"seo":{"title":"Salsa inglesa casera rápida con tamarindo","description":"Prepara salsa inglesa casera con vinagre, tamarindo, melaza y soja. Una versión rápida sin fermentación para sazonar carnes, verduras y guisos.","image_alt":"Salsa inglesa casera rápida con tamarindo","faq":[{"q":"¿Es igual a la salsa inglesa comercial?","a":"Es una alternativa casera rápida, ácida y especiada. No lleva añejamiento ni fermentación, por lo que el sabor es distinto."},{"q":"¿Cómo se usa?","a":"Añade pequeñas cantidades a marinadas, guisos, hamburguesas, champiñones o aderezos. Prueba antes de agregar más sal."},{"q":"¿Puedo usar concentrado de tamarindo?","a":"Esta receta usa pasta sin semillas y sin azúcar, no concentrado. La intensidad varía mucho: no sustituyas uno por otro en la misma cantidad."}],"image_variants":["/recetas/salsa-inglesa-casera/portada-1x1.webp","/recetas/salsa-inglesa-casera/portada-4x3.webp","/recetas/salsa-inglesa-casera/portada-16x9.webp"]},"nutrition":{"calories":14,"protein_g":0.3,"carbs_g":2.7,"fat_g":0.1,"sodium_mg":150,"serving_size":"15 ml (1 de 20 porciones)","estimated":true,"source":"USDA FoodData Central: generic ingredient composition; estimate","method":"Suma aproximada de ingredientes antes de colar dividida entre 20 porciones de un rendimiento final de 300 ml.","note":"Estimación con todos los ingredientes antes de colar; puede sobreestimar los sólidos retenidos. El sodio varía según la soja. Rendimiento aproximado: 300 ml."}},{"language":"en","slug":"quick-homemade-worcestershire-sauce","public_path":"/en/quick-homemade-worcestershire-sauce","title":"Quick homemade Worcestershire-style sauce","excerpt":"Make a quick Worcestershire-style sauce with cider vinegar, tamarind, molasses and soy sauce. A tangy homemade seasoning without fermentation.","summary":"Make a quick Worcestershire-style sauce with cider vinegar, tamarind, molasses and soy sauce. A tangy homemade seasoning without fermentation.","ingredients":[{"amount":"250","unit":"ml","name":"apple cider vinegar, 5% acidity"},{"amount":"100","unit":"ml","name":"water"},{"amount":"50","unit":"ml","name":"soy sauce"},{"amount":"40","unit":"g","name":"cane molasses"},{"amount":"20","unit":"g","name":"unsweetened seedless tamarind paste"},{"amount":"30","unit":"g","name":"white onion"},{"amount":"5","unit":"g","name":"peeled garlic"},{"amount":"5","unit":"g","name":"peeled fresh ginger"},{"amount":"0.5","unit":"g","name":"ground black pepper"},{"amount":"2","unit":"","name":"whole cloves"},{"amount":"2","unit":"","name":"whole allspice berries"}],"steps":[{"title":"Measure the ingredients","content":"Measure the listed quantities. Set out a clean capped bottle and a measuring jug.","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp","image_alt":"Measure the ingredients"},{"title":"Chop the aromatics","content":"Finely chop the onion, garlic and ginger.","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp","image_alt":"Chop the aromatics"},{"title":"Combine the liquids","content":"Pour the vinegar, 100 ml water and soy sauce into a 1-litre stainless-steel saucepan.","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp","image_alt":"Combine the liquids"},{"title":"Dissolve the molasses and tamarind","content":"Stir in the molasses and tamarind paste until dispersed.","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp","image_alt":"Dissolve the molasses and tamarind"},{"title":"Add aromatics and spices","content":"Add the onion, garlic, ginger, black pepper, cloves and allspice.","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp","image_alt":"Add aromatics and spices"},{"title":"Heat the mixture","content":"Bring to a gentle boil over medium heat, about 5 minutes."},{"title":"Simmer gently","content":"Reduce the heat and simmer uncovered for 20 minutes with small bubbles. Stir occasionally; the sauce should stay thin.","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp","image_alt":"Simmer gently"},{"title":"Strain the sauce","content":"Strain the hot sauce through a fine sieve into a heatproof jug. Discard the solids.","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp","image_alt":"Strain the sauce"},{"title":"Cool the sauce","content":"Let the strong heat dissipate for about 30 minutes. Do not leave unrefrigerated for more than 2 hours."},{"title":"Check the yield","content":"Measure the strained sauce: the approximate yield is 300 ml. If it reduced too far, add a little freshly boiled water to reach 300 ml."},{"title":"Refrigerate","content":"Transfer to the clean bottle, cap and refrigerate. Use clean utensils and shake before serving.","image_url":"/recetas/salsa-inglesa-casera/portada.webp","image_alt":"Refrigerate"}],"category":"Sauces & dressings","cuisine":"British-inspired","difficulty":"Easy","course":"Condiment","prep_time_minutes":10,"cook_time_minutes":25,"total_time_minutes":65,"servings":20,"image_url":"/recetas/salsa-inglesa-casera/portada.webp","content_html":"","notes":"<p>A quick homemade Worcestershire-style sauce, without commercial fermentation or ageing. Contains soy and may contain wheat; check the soy sauce label. Taste before adding salt. Start with 1 teaspoon per serving of stew or dressing. Refrigerate at 4 °C or below and use within 4 days; freeze portions for longer storage. Not a shelf-stable preserve.</p>","keywords":["Quick homemade Worcestershire-style sauce"],"seo":{"title":"Quick homemade Worcestershire-style sauce","description":"Make a quick Worcestershire-style sauce with cider vinegar, tamarind, molasses and soy sauce. A tangy homemade seasoning without fermentation.","image_alt":"Quick homemade Worcestershire-style sauce","faq":[{"q":"Does it taste exactly like bottled Worcestershire?","a":"It is a tangy, spiced homemade alternative. Without fermentation or ageing, its flavour is different."},{"q":"How do I use it?","a":"Add small amounts to marinades, stews, burgers, mushrooms or dressings. Taste before adding more salt."},{"q":"Can I use tamarind concentrate?","a":"This recipe uses unsweetened seedless paste, not concentrate. Strength varies widely; do not substitute equal quantities."}],"image_variants":["/recetas/salsa-inglesa-casera/portada-1x1.webp","/recetas/salsa-inglesa-casera/portada-4x3.webp","/recetas/salsa-inglesa-casera/portada-16x9.webp"]},"nutrition":{"calories":14,"protein_g":0.3,"carbs_g":2.7,"fat_g":0.1,"sodium_mg":150,"serving_size":"15 ml (one of 20 servings)","estimated":true,"source":"USDA FoodData Central: generic ingredient composition; estimate","method":"Approximate sum of ingredients before straining, divided by 20 portions from a final 300 ml yield.","note":"Estimate includes all ingredients before straining and may overestimate retained solids. Sodium varies by soy sauce. Approximate yield: 300 ml."}},{"language":"de","slug":"schnelle-worcestersauce-selber-machen","public_path":"/de/schnelle-worcestersauce-selber-machen","title":"Schnelle Worcestersauce selber machen","excerpt":"Worcestersauce nach Hausart mit Apfelessig, Tamarinde, Melasse und Sojasauce: eine schnelle Würzsauce ohne Fermentation für Gemüse und Schmorgerichte.","summary":"Worcestersauce nach Hausart mit Apfelessig, Tamarinde, Melasse und Sojasauce: eine schnelle Würzsauce ohne Fermentation für Gemüse und Schmorgerichte.","ingredients":[{"amount":"250","unit":"ml","name":"Apfelessig mit 5 % Säure"},{"amount":"100","unit":"ml","name":"Wasser"},{"amount":"50","unit":"ml","name":"Sojasauce"},{"amount":"40","unit":"g","name":"Zuckerrohrmelasse"},{"amount":"20","unit":"g","name":"ungesüßte kernlose Tamarindenpaste"},{"amount":"30","unit":"g","name":"weiße Zwiebel"},{"amount":"5","unit":"g","name":"geschälter Knoblauch"},{"amount":"5","unit":"g","name":"geschälter frischer Ingwer"},{"amount":"0.5","unit":"g","name":"gemahlener schwarzer Pfeffer"},{"amount":"2","unit":"","name":"ganze Gewürznelken"},{"amount":"2","unit":"","name":"Pimentkörner"}],"steps":[{"title":"Zutaten abmessen","content":"Alle Mengen abmessen. Eine saubere Flasche mit Deckel und einen Messbecher bereitstellen.","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp","image_alt":"Zutaten abmessen"},{"title":"Aromaten hacken","content":"Zwiebel, Knoblauch und Ingwer fein hacken.","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp","image_alt":"Aromaten hacken"},{"title":"Flüssigkeiten mischen","content":"Essig, 100 ml Wasser und Sojasauce in einen 1-Liter-Edelstahltopf gießen.","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp","image_alt":"Flüssigkeiten mischen"},{"title":"Melasse und Tamarinde einrühren","content":"Melasse und Tamarindenpaste einrühren, bis sie sich verteilt haben.","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp","image_alt":"Melasse und Tamarinde einrühren"},{"title":"Aromaten und Gewürze zugeben","content":"Zwiebel, Knoblauch, Ingwer, Pfeffer, Nelken und Piment zugeben.","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp","image_alt":"Aromaten und Gewürze zugeben"},{"title":"Mischung erhitzen","content":"Bei mittlerer Hitze in etwa 5 Minuten sanft aufkochen."},{"title":"Sanft köcheln","content":"Die Hitze reduzieren und offen 20 Minuten mit kleinen Blasen köcheln lassen. Gelegentlich rühren; die Sauce bleibt dünnflüssig.","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp","image_alt":"Sanft köcheln"},{"title":"Sauce abseihen","content":"Die heiße Sauce durch ein feines Sieb in einen hitzefesten Messbecher gießen. Die festen Reste entsorgen.","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp","image_alt":"Sauce abseihen"},{"title":"Sauce abkühlen","content":"Etwa 30 Minuten abkühlen lassen. Insgesamt nicht länger als 2 Stunden ungekühlt stehen lassen."},{"title":"Menge prüfen","content":"Die abgeseihte Sauce ergibt ungefähr 300 ml. Bei zu starker Reduktion etwas frisch aufgekochtes Wasser bis 300 ml ergänzen."},{"title":"Kühl lagern","content":"In die saubere Flasche füllen, verschließen und kühlen. Saubere Utensilien verwenden und vor Gebrauch schütteln.","image_url":"/recetas/salsa-inglesa-casera/portada.webp","image_alt":"Kühl lagern"}],"category":"Saucen und Dressings","cuisine":"Britisch inspiriert","difficulty":"Einfach","course":"Würzsauce","prep_time_minutes":10,"cook_time_minutes":25,"total_time_minutes":65,"servings":20,"image_url":"/recetas/salsa-inglesa-casera/portada.webp","content_html":"","notes":"<p>Schnelle Würzsauce nach Worcestershire-Art ohne Fermentation oder Reifung. Enthält Soja und möglicherweise Weizen; Etikett prüfen. Erst kosten, dann salzen. Mit 1 TL pro Portion Schmorgericht oder Dressing beginnen. Bei höchstens 4 °C lagern und innerhalb von 4 Tagen verbrauchen; für längere Lagerung portionsweise einfrieren. Nicht ungekühlt haltbar.</p>","keywords":["Schnelle Worcestersauce selber machen"],"seo":{"title":"Schnelle Worcestersauce selber machen","description":"Worcestersauce nach Hausart mit Apfelessig, Tamarinde, Melasse und Sojasauce: eine schnelle Würzsauce ohne Fermentation für Gemüse und Schmorgerichte.","image_alt":"Schnelle Worcestersauce selber machen","faq":[{"q":"Schmeckt sie wie gekaufte Worcestersauce?","a":"Sie ist eine säuerliche, würzige Alternative. Ohne Fermentation und Reifung schmeckt sie anders."},{"q":"Wofür eignet sie sich?","a":"Kleine Mengen in Marinaden, Schmorgerichten, Burgern, Pilzen oder Dressings verwenden. Vor weiterem Salzen probieren."},{"q":"Geht Tamarindenkonzentrat?","a":"Verwendet wird ungesüßte kernlose Paste. Konzentrate sind unterschiedlich stark und lassen sich nicht mengenmäßig gleich ersetzen."}],"image_variants":["/recetas/salsa-inglesa-casera/portada-1x1.webp","/recetas/salsa-inglesa-casera/portada-4x3.webp","/recetas/salsa-inglesa-casera/portada-16x9.webp"]},"nutrition":{"calories":14,"protein_g":0.3,"carbs_g":2.7,"fat_g":0.1,"sodium_mg":150,"serving_size":"15 ml (eine von 20 Portionen)","estimated":true,"source":"USDA FoodData Central: generic ingredient composition; estimate","method":"Nährwerte aller Zutaten vor dem Abseihen, geteilt durch 20 Portionen bei etwa 300 ml Endmenge.","note":"Schätzung aller Zutaten vor dem Abseihen; feste Rückstände können die Werte verringern. Natrium hängt von der Sojasauce ab. Ergibt etwa 300 ml."}},{"language":"fr","slug":"sauce-worcestershire-maison-rapide","public_path":"/fr/sauce-worcestershire-maison-rapide","title":"Sauce Worcestershire maison rapide","excerpt":"Préparez une sauce façon Worcestershire avec vinaigre de cidre, tamarin, mélasse et soja. Une version maison rapide, acidulée et sans fermentation.","summary":"Préparez une sauce façon Worcestershire avec vinaigre de cidre, tamarin, mélasse et soja. Une version maison rapide, acidulée et sans fermentation.","ingredients":[{"amount":"250","unit":"ml","name":"vinaigre de cidre à 5 % d’acidité"},{"amount":"100","unit":"ml","name":"eau"},{"amount":"50","unit":"ml","name":"sauce soja"},{"amount":"40","unit":"g","name":"mélasse de canne"},{"amount":"20","unit":"g","name":"pâte de tamarin sans graines et sans sucre"},{"amount":"30","unit":"g","name":"oignon blanc"},{"amount":"5","unit":"g","name":"ail pelé"},{"amount":"5","unit":"g","name":"gingembre frais pelé"},{"amount":"0.5","unit":"g","name":"poivre noir moulu"},{"amount":"2","unit":"","name":"clous de girofle entiers"},{"amount":"2","unit":"","name":"grains de piment de la Jamaïque"}],"steps":[{"title":"Mesurez les ingrédients","content":"Mesurez les quantités indiquées. Préparez une bouteille propre avec bouchon et un verre doseur.","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp","image_alt":"Mesurez les ingrédients"},{"title":"Hachez les aromates","content":"Hachez finement l’oignon, l’ail et le gingembre.","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp","image_alt":"Hachez les aromates"},{"title":"Mélangez les liquides","content":"Versez le vinaigre, les 100 ml d’eau et la sauce soja dans une casserole inox de 1 litre.","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp","image_alt":"Mélangez les liquides"},{"title":"Incorporez mélasse et tamarin","content":"Incorporez la mélasse et la pâte de tamarin en remuant pour les disperser.","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp","image_alt":"Incorporez mélasse et tamarin"},{"title":"Ajoutez aromates et épices","content":"Ajoutez oignon, ail, gingembre, poivre, girofle et piment de la Jamaïque.","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp","image_alt":"Ajoutez aromates et épices"},{"title":"Chauffez le mélange","content":"Portez à légère ébullition à feu moyen, environ 5 minutes."},{"title":"Laissez frémir","content":"Baissez le feu et laissez frémir à découvert 20 minutes. Remuez de temps en temps ; la sauce doit rester fluide.","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp","image_alt":"Laissez frémir"},{"title":"Filtrez la sauce","content":"Filtrez la sauce chaude au tamis fin dans un récipient résistant à la chaleur. Jetez les solides.","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp","image_alt":"Filtrez la sauce"},{"title":"Refroidissez la sauce","content":"Laissez perdre la forte chaleur environ 30 minutes. Ne laissez pas plus de 2 heures hors du réfrigérateur."},{"title":"Vérifiez le volume","content":"Le volume filtré est d’environ 300 ml. Si la sauce a trop réduit, complétez avec un peu d’eau fraîchement bouillie jusqu’à 300 ml."},{"title":"Conservez au réfrigérateur","content":"Versez dans la bouteille propre, fermez et réfrigérez. Utilisez des ustensiles propres et secouez avant usage.","image_url":"/recetas/salsa-inglesa-casera/portada.webp","image_alt":"Conservez au réfrigérateur"}],"category":"Sauces et vinaigrettes","cuisine":"Inspiration britannique","difficulty":"Facile","course":"Condiment","prep_time_minutes":10,"cook_time_minutes":25,"total_time_minutes":65,"servings":20,"image_url":"/recetas/salsa-inglesa-casera/portada.webp","content_html":"","notes":"<p>Version maison rapide façon Worcestershire, sans fermentation ni maturation. Contient du soja et peut contenir du blé : vérifiez l’étiquette. Goûtez avant de saler. Commencez par 1 cuillère à café par portion de plat mijoté ou de vinaigrette. Gardez à 4 °C maximum et utilisez sous 4 jours ; congelez de petites portions pour plus longtemps. Ce n’est pas une conserve à température ambiante.</p>","keywords":["Sauce Worcestershire maison rapide"],"seo":{"title":"Sauce Worcestershire maison rapide","description":"Préparez une sauce façon Worcestershire avec vinaigre de cidre, tamarin, mélasse et soja. Une version maison rapide, acidulée et sans fermentation.","image_alt":"Sauce Worcestershire maison rapide","faq":[{"q":"Est-elle identique à la sauce du commerce ?","a":"C’est une alternative acidulée et épicée. Sans fermentation ni maturation, son goût reste différent."},{"q":"Comment l’utiliser ?","a":"Ajoutez-en peu à peu aux marinades, plats mijotés, burgers, champignons ou vinaigrettes. Goûtez avant de saler davantage."},{"q":"Peut-on utiliser du concentré de tamarin ?","a":"La recette emploie une pâte sans graines ni sucre. La force des concentrés varie : ne remplacez pas à quantité égale."}],"image_variants":["/recetas/salsa-inglesa-casera/portada-1x1.webp","/recetas/salsa-inglesa-casera/portada-4x3.webp","/recetas/salsa-inglesa-casera/portada-16x9.webp"]},"nutrition":{"calories":14,"protein_g":0.3,"carbs_g":2.7,"fat_g":0.1,"sodium_mg":150,"serving_size":"15 ml (une portion sur 20)","estimated":true,"source":"USDA FoodData Central: generic ingredient composition; estimate","method":"Somme approximative des ingrédients avant filtration, divisée par 20 portions pour 300 ml de sauce.","note":"Estimation avant filtration incluant tous les ingrédients ; les solides retirés peuvent réduire les valeurs. Sodium variable selon la sauce soja. Rendement : environ 300 ml."}},{"language":"it","slug":"salsa-worcestershire-fatta-in-casa-veloce","public_path":"/it/salsa-worcestershire-fatta-in-casa-veloce","title":"Salsa Worcestershire fatta in casa veloce","excerpt":"Una salsa tipo Worcestershire con aceto di mele, tamarindo, melassa e soia. Ricetta casalinga veloce, senza fermentazione, per insaporire i piatti.","summary":"Una salsa tipo Worcestershire con aceto di mele, tamarindo, melassa e soia. Ricetta casalinga veloce, senza fermentazione, per insaporire i piatti.","ingredients":[{"amount":"250","unit":"ml","name":"aceto di mele al 5% di acidità"},{"amount":"100","unit":"ml","name":"acqua"},{"amount":"50","unit":"ml","name":"salsa di soia"},{"amount":"40","unit":"g","name":"melassa di canna"},{"amount":"20","unit":"g","name":"pasta di tamarindo senza semi e senza zucchero"},{"amount":"30","unit":"g","name":"cipolla bianca"},{"amount":"5","unit":"g","name":"aglio sbucciato"},{"amount":"5","unit":"g","name":"zenzero fresco pelato"},{"amount":"0.5","unit":"g","name":"pepe nero macinato"},{"amount":"2","unit":"","name":"chiodi di garofano interi"},{"amount":"2","unit":"","name":"grani di pimento"}],"steps":[{"title":"Misura gli ingredienti","content":"Misura le quantità indicate. Prepara una bottiglia pulita con tappo e una caraffa graduata.","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp","image_alt":"Misura gli ingredienti"},{"title":"Trita gli aromi","content":"Trita finemente cipolla, aglio e zenzero.","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp","image_alt":"Trita gli aromi"},{"title":"Unisci i liquidi","content":"Versa aceto, 100 ml di acqua e salsa di soia in un pentolino inox da 1 litro.","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp","image_alt":"Unisci i liquidi"},{"title":"Sciogli melassa e tamarindo","content":"Incorpora melassa e pasta di tamarindo mescolando per distribuirle.","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp","image_alt":"Sciogli melassa e tamarindo"},{"title":"Aggiungi aromi e spezie","content":"Aggiungi cipolla, aglio, zenzero, pepe, chiodi di garofano e pimento.","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp","image_alt":"Aggiungi aromi e spezie"},{"title":"Scalda il composto","content":"Porta a leggero bollore a fuoco medio, circa 5 minuti."},{"title":"Fai sobbollire","content":"Abbassa il fuoco e fai sobbollire scoperto per 20 minuti. Mescola ogni tanto; la salsa deve restare fluida.","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp","image_alt":"Fai sobbollire"},{"title":"Filtra la salsa","content":"Filtra la salsa calda con un colino fine in una caraffa resistente al calore. Elimina i solidi.","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp","image_alt":"Filtra la salsa"},{"title":"Raffredda la salsa","content":"Lascia perdere il calore intenso per circa 30 minuti. Non lasciare fuori dal frigorifero per oltre 2 ore."},{"title":"Controlla la resa","content":"La resa filtrata è di circa 300 ml. Se è diminuita troppo, aggiungi poca acqua appena bollita fino a 300 ml."},{"title":"Conserva in frigorifero","content":"Trasferisci nella bottiglia pulita, chiudi e metti in frigorifero. Usa utensili puliti e agita prima di servire.","image_url":"/recetas/salsa-inglesa-casera/portada.webp","image_alt":"Conserva in frigorifero"}],"category":"Salse e condimenti","cuisine":"Ispirazione britannica","difficulty":"Facile","course":"Condimento","prep_time_minutes":10,"cook_time_minutes":25,"total_time_minutes":65,"servings":20,"image_url":"/recetas/salsa-inglesa-casera/portada.webp","content_html":"","notes":"<p>Versione casalinga rapida in stile Worcestershire, senza fermentazione o maturazione. Contiene soia e può contenere frumento: controlla l’etichetta. Assaggia prima di salare. Inizia con 1 cucchiaino per porzione di stufato o condimento. Conserva a massimo 4 °C e usa entro 4 giorni; congela piccole porzioni per tempi più lunghi. Non è una conserva da tenere a temperatura ambiente.</p>","keywords":["Salsa Worcestershire fatta in casa veloce"],"seo":{"title":"Salsa Worcestershire fatta in casa veloce","description":"Una salsa tipo Worcestershire con aceto di mele, tamarindo, melassa e soia. Ricetta casalinga veloce, senza fermentazione, per insaporire i piatti.","image_alt":"Salsa Worcestershire fatta in casa veloce","faq":[{"q":"È uguale a quella commerciale?","a":"È un’alternativa acidula e speziata. Senza fermentazione o maturazione il gusto è diverso."},{"q":"Come si usa?","a":"Aggiungine piccole quantità a marinate, stufati, hamburger, funghi o condimenti. Assaggia prima di aggiungere altro sale."},{"q":"Posso usare il concentrato di tamarindo?","a":"Qui serve pasta senza semi e senza zucchero. I concentrati hanno intensità variabili: non sostituirli a pari quantità."}],"image_variants":["/recetas/salsa-inglesa-casera/portada-1x1.webp","/recetas/salsa-inglesa-casera/portada-4x3.webp","/recetas/salsa-inglesa-casera/portada-16x9.webp"]},"nutrition":{"calories":14,"protein_g":0.3,"carbs_g":2.7,"fat_g":0.1,"sodium_mg":150,"serving_size":"15 ml (una di 20 porzioni)","estimated":true,"source":"USDA FoodData Central: generic ingredient composition; estimate","method":"Somma approssimativa degli ingredienti prima del filtraggio, divisa per 20 porzioni su 300 ml finali.","note":"Stima di tutti gli ingredienti prima di filtrare; i solidi eliminati possono ridurre i valori. Il sodio varia con la soia. Resa: circa 300 ml."}},{"language":"pt","slug":"molho-ingles-caseiro-rapido","public_path":"/pt/molho-ingles-caseiro-rapido","title":"Molho inglês caseiro rápido com tamarindo","excerpt":"Faça molho inglês caseiro com vinagre de maçã, tamarindo, melaço e shoyu. Uma versão rápida sem fermentação para temperar carnes, legumes e ensopados.","summary":"Faça molho inglês caseiro com vinagre de maçã, tamarindo, melaço e shoyu. Uma versão rápida sem fermentação para temperar carnes, legumes e ensopados.","ingredients":[{"amount":"250","unit":"ml","name":"vinagre de maçã com 5% de acidez"},{"amount":"100","unit":"ml","name":"água"},{"amount":"50","unit":"ml","name":"molho de soja (shoyu)"},{"amount":"40","unit":"g","name":"melaço de cana"},{"amount":"20","unit":"g","name":"pasta de tamarindo sem sementes e sem açúcar"},{"amount":"30","unit":"g","name":"cebola branca"},{"amount":"5","unit":"g","name":"alho descascado"},{"amount":"5","unit":"g","name":"gengibre fresco descascado"},{"amount":"0.5","unit":"g","name":"pimenta-do-reino moída"},{"amount":"2","unit":"","name":"cravos-da-índia inteiros"},{"amount":"2","unit":"","name":"grãos de pimenta-da-jamaica"}],"steps":[{"title":"Meça os ingredientes","content":"Meça as quantidades indicadas. Separe uma garrafa limpa com tampa e uma jarra graduada.","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp","image_alt":"Meça os ingredientes"},{"title":"Pique os aromáticos","content":"Pique bem a cebola, o alho e o gengibre.","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp","image_alt":"Pique os aromáticos"},{"title":"Misture os líquidos","content":"Coloque vinagre, 100 ml de água e shoyu numa panela inox de 1 litro.","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp","image_alt":"Misture os líquidos"},{"title":"Dissolva o melaço e o tamarindo","content":"Adicione melaço e pasta de tamarindo, mexendo para dispersar.","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp","image_alt":"Dissolva o melaço e o tamarindo"},{"title":"Adicione aromáticos e especiarias","content":"Junte cebola, alho, gengibre, pimenta-do-reino, cravo e pimenta-da-jamaica.","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp","image_alt":"Adicione aromáticos e especiarias"},{"title":"Aqueça a mistura","content":"Leve à fervura suave em fogo médio, cerca de 5 minutos."},{"title":"Cozinhe em fogo baixo","content":"Baixe o fogo e cozinhe destampado por 20 minutos, com bolhas pequenas. Mexa de vez em quando; o molho deve ficar fluido.","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp","image_alt":"Cozinhe em fogo baixo"},{"title":"Coe o molho","content":"Coe o molho quente em peneira fina para uma jarra resistente ao calor. Descarte os sólidos.","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp","image_alt":"Coe o molho"},{"title":"Esfrie o molho","content":"Deixe perder o calor intenso por cerca de 30 minutos. Não mantenha fora da geladeira por mais de 2 horas."},{"title":"Confira o rendimento","content":"O rendimento coado é de aproximadamente 300 ml. Se reduzir demais, complete com pouca água recém-fervida até 300 ml."},{"title":"Guarde na geladeira","content":"Transfira para a garrafa limpa, tampe e refrigere. Use utensílios limpos e agite antes de servir.","image_url":"/recetas/salsa-inglesa-casera/portada.webp","image_alt":"Guarde na geladeira"}],"category":"Molhos e temperos","cuisine":"Inspiração britânica","difficulty":"Fácil","course":"Condimento","prep_time_minutes":10,"cook_time_minutes":25,"total_time_minutes":65,"servings":20,"image_url":"/recetas/salsa-inglesa-casera/portada.webp","content_html":"","notes":"<p>Versão caseira rápida inspirada no molho Worcestershire, sem fermentação ou maturação. Contém soja e pode conter trigo: confira o rótulo. Prove antes de salgar. Comece com 1 colher de chá por porção de ensopado ou tempero. Guarde a 4 °C ou menos e use em 4 dias; congele porções para conservar por mais tempo. Não é conserva estável fora da geladeira.</p>","keywords":["Molho inglês caseiro rápido com tamarindo"],"seo":{"title":"Molho inglês caseiro rápido com tamarindo","description":"Faça molho inglês caseiro com vinagre de maçã, tamarindo, melaço e shoyu. Uma versão rápida sem fermentação para temperar carnes, legumes e ensopados.","image_alt":"Molho inglês caseiro rápido com tamarindo","faq":[{"q":"É igual ao molho inglês industrializado?","a":"É uma alternativa caseira ácida e aromática. Sem fermentação ou maturação, o sabor é diferente."},{"q":"Como usar?","a":"Acrescente pequenas quantidades a marinadas, ensopados, hambúrgueres, cogumelos ou molhos de salada. Prove antes de colocar mais sal."},{"q":"Posso usar concentrado de tamarindo?","a":"Aqui usamos pasta sem sementes e sem açúcar. A força dos concentrados varia; não substitua pela mesma quantidade."}],"image_variants":["/recetas/salsa-inglesa-casera/portada-1x1.webp","/recetas/salsa-inglesa-casera/portada-4x3.webp","/recetas/salsa-inglesa-casera/portada-16x9.webp"]},"nutrition":{"calories":14,"protein_g":0.3,"carbs_g":2.7,"fat_g":0.1,"sodium_mg":150,"serving_size":"15 ml (uma de 20 porções)","estimated":true,"source":"USDA FoodData Central: generic ingredient composition; estimate","method":"Soma aproximada dos ingredientes antes de coar, dividida por 20 porções de um rendimento de 300 ml.","note":"Estimativa de todos os ingredientes antes de coar; os sólidos retirados podem reduzir os valores. Sódio variável conforme o shoyu. Rendimento aproximado: 300 ml."}},{"language":"ja","slug":"tezukuri-worcestershire-sauce","public_path":"/ja/tezukuri-worcestershire-sauce","title":"手作りウスター風ソース・発酵なし","excerpt":"りんご酢、タマリンド、糖蜜、しょうゆで作る手作りウスター風ソース。発酵なしで作る、肉や野菜、煮込み料理向けの酸味のある調味料です。","summary":"りんご酢、タマリンド、糖蜜、しょうゆで作る手作りウスター風ソース。発酵なしで作る、肉や野菜、煮込み料理向けの酸味のある調味料です。","ingredients":[{"amount":"250","unit":"ml","name":"りんご酢（酸度5％）"},{"amount":"100","unit":"ml","name":"水"},{"amount":"50","unit":"ml","name":"しょうゆ"},{"amount":"40","unit":"g","name":"サトウキビ糖蜜"},{"amount":"20","unit":"g","name":"無糖・種なしタマリンドペースト"},{"amount":"30","unit":"g","name":"白玉ねぎ"},{"amount":"5","unit":"g","name":"皮をむいたにんにく"},{"amount":"5","unit":"g","name":"皮をむいたしょうが"},{"amount":"0.5","unit":"g","name":"黒こしょう（粉）"},{"amount":"2","unit":"","name":"クローブ（ホール）"},{"amount":"2","unit":"","name":"オールスパイス（ホール）"}],"steps":[{"title":"材料を量る","content":"分量を量ります。ふた付きの清潔な瓶と計量カップを用意します。","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp","image_alt":"材料を量る"},{"title":"香味野菜を刻む","content":"玉ねぎ、にんにく、しょうがを細かく刻みます。","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp","image_alt":"香味野菜を刻む"},{"title":"液体を合わせる","content":"容量1リットルのステンレス小鍋に酢、水100 ml、しょうゆを入れます。","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp","image_alt":"液体を合わせる"},{"title":"糖蜜とタマリンドを混ぜる","content":"糖蜜とタマリンドペーストを加え、全体に行き渡るまで混ぜます。","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp","image_alt":"糖蜜とタマリンドを混ぜる"},{"title":"香味野菜とスパイスを加える","content":"玉ねぎ、にんにく、しょうが、黒こしょう、クローブ、オールスパイスを加えます。","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp","image_alt":"香味野菜とスパイスを加える"},{"title":"温める","content":"中火で約5分、穏やかに沸くまで温めます。"},{"title":"弱火で煮る","content":"弱火にしてふたをせず20分煮ます。時々混ぜ、小さな泡が立つ程度を保ちます。さらりと仕上げます。","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp","image_alt":"弱火で煮る"},{"title":"ソースをこす","content":"熱いうちに細かいざるで耐熱容器へこします。残った固形物は捨てます。","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp","image_alt":"ソースをこす"},{"title":"粗熱を取る","content":"約30分置いて強い熱を取ります。冷蔵庫の外に2時間以上放置しないでください。"},{"title":"出来上がり量を確認する","content":"出来上がりは約300 mlです。煮詰まりすぎた場合は、沸かしたばかりの湯を少量加えて300 mlにします。"},{"title":"冷蔵する","content":"清潔な瓶に移し、ふたをして冷蔵します。清潔な器具を使い、使用前によく振ります。","image_url":"/recetas/salsa-inglesa-casera/portada.webp","image_alt":"冷蔵する"}],"category":"ソース・ドレッシング","cuisine":"イギリス風","difficulty":"簡単","course":"調味料","prep_time_minutes":10,"cook_time_minutes":25,"total_time_minutes":65,"servings":20,"image_url":"/recetas/salsa-inglesa-casera/portada.webp","content_html":"","notes":"<p>発酵や熟成を行わない、手作りウスター風ソースです。市販品とは風味が異なります。大豆を含み、しょうゆによっては小麦も含むため表示を確認してください。塩を足す前に味見します。煮込みやドレッシング1人分に小さじ1から試してください。4 °C以下で冷蔵し、4日以内に使い切ります。長く保存する場合は小分け冷凍してください。常温保存用の瓶詰めではありません。</p>","keywords":["手作りウスター風ソース・発酵なし"],"seo":{"title":"手作りウスター風ソース・発酵なし","description":"りんご酢、タマリンド、糖蜜、しょうゆで作る手作りウスター風ソース。発酵なしで作る、肉や野菜、煮込み料理向けの酸味のある調味料です。","image_alt":"手作りウスター風ソース・発酵なし","faq":[{"q":"市販のウスターソースと同じですか？","a":"酸味とスパイスを生かした家庭向けの代用品です。発酵や熟成をしないので味は異なります。"},{"q":"何に使えますか？","a":"マリネ、煮込み、ハンバーガー、きのこ料理、ドレッシングに少量ずつ加えます。塩を足す前に味見してください。"},{"q":"タマリンド濃縮液でも作れますか？","a":"この分量は無糖・種なしペースト用です。濃縮品は濃さが異なるため同量で置き換えないでください。"}],"image_variants":["/recetas/salsa-inglesa-casera/portada-1x1.webp","/recetas/salsa-inglesa-casera/portada-4x3.webp","/recetas/salsa-inglesa-casera/portada-16x9.webp"]},"nutrition":{"calories":14,"protein_g":0.3,"carbs_g":2.7,"fat_g":0.1,"sodium_mg":150,"serving_size":"15 ml（全20回分の1回分）","estimated":true,"source":"USDA FoodData Central: generic ingredient composition; estimate","method":"こす前の全材料の栄養量を概算し、出来上がり300 mlの20回分で割っています。","note":"こす前の全材料から算出した目安で、取り除く固形物の分も含みます。ナトリウム量はしょうゆで変わります。出来上がり約300 ml。"}}]$data$::jsonb; n integer;
BEGIN
PERFORM 1 FROM public.recipes WHERE recipe_group_id='8b063804-3338-4cdf-b5db-ddfbac5c8eb3' FOR UPDATE;
IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id='8b063804-3338-4cdf-b5db-ddfbac5c8eb3')<>1 OR NOT EXISTS(SELECT 1 FROM public.recipes WHERE id='0355e565-2ff2-4b93-9451-b9d39e92426e' AND published=false AND updated_at='2026-10-07 01:12:39.564667+00') THEN RAISE EXCEPTION 'Estado inicial cambió'; END IF;
IF EXISTS(SELECT 1 FROM public.recipes WHERE public_path IN(SELECT x->>'public_path' FROM jsonb_array_elements(payload)x WHERE x->>'language'<>'es')) OR EXISTS(SELECT 1 FROM public.content_pages WHERE public_path IN(SELECT x->>'public_path' FROM jsonb_array_elements(payload)x)) THEN RAISE EXCEPTION 'Colisión de URL'; END IF;
UPDATE public.recipes r SET slug=s.slug,title=s.title,excerpt=s.excerpt,ingredients=s.ingredients,steps=s.steps,category=s.category,prep_time_minutes=s.prep_time_minutes,cook_time_minutes=s.cook_time_minutes,servings=s.servings,image_url=s.image_url,content_html=s.content_html,summary=s.summary,notes=s.notes,difficulty=s.difficulty,course=s.course,cuisine=s.cuisine,total_time_minutes=s.total_time_minutes,keywords=s.keywords,nutrition=s.nutrition,seo=s.seo,public_path=s.public_path,gallery='[]'::jsonb,video_urls='[]'::jsonb,published=true,editorial_status='published',ready_at=now(),reviewed_at=now()
FROM jsonb_populate_recordset(NULL::public.recipes,payload)s WHERE r.id='0355e565-2ff2-4b93-9451-b9d39e92426e' AND s.language='es';
INSERT INTO public.recipes(recipe_group_id,language,slug,title,excerpt,ingredients,steps,category,prep_time_minutes,cook_time_minutes,servings,image_url,content_html,summary,notes,difficulty,course,cuisine,total_time_minutes,keywords,nutrition,seo,public_path,gallery,video_urls,published,editorial_status,ready_at,reviewed_at)
SELECT '8b063804-3338-4cdf-b5db-ddfbac5c8eb3'::uuid,s.language,s.slug,s.title,s.excerpt,s.ingredients,s.steps,s.category,s.prep_time_minutes,s.cook_time_minutes,s.servings,s.image_url,s.content_html,s.summary,s.notes,s.difficulty,s.course,s.cuisine,s.total_time_minutes,s.keywords,s.nutrition,s.seo,s.public_path,'[]'::jsonb,'[]'::jsonb,true,'published',now(),now() FROM jsonb_populate_recordset(NULL::public.recipes,payload)s WHERE s.language<>'es';
DELETE FROM public.content_redirects WHERE source_path IN(SELECT x->>'public_path' FROM jsonb_array_elements(payload)x) AND status_code IN(302,307);
SELECT count(DISTINCT language) INTO n FROM public.recipes WHERE recipe_group_id='8b063804-3338-4cdf-b5db-ddfbac5c8eb3' AND published AND ready_at IS NOT NULL AND nutrition->>'calories' IS NOT NULL;
IF n<>7 THEN RAISE EXCEPTION 'Publicación incompleta'; END IF;
END $block$;
COMMIT;
